async function api(path,opt={}){let r;try{r=await fetch(path,{credentials:'same-origin',cache:'no-store',...opt,headers:{Accept:'application/json','Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{}),...(opt.headers||{})}})}catch(_){throw Error('تعذر الاتصال بخادم ZILL؛ شغّل server.py وافتح عنوان الخادم.')}if(!(r.headers.get('content-type')||'').toLowerCase().includes('application/json')){if(r.status===404&&path.startsWith('/api/'))throw Error('خادم API غير موجود على هذا النطاق. يبدو أن الاستضافة نشرت ملفات الواجهة فقط؛ يجب تشغيل server.py كخادم Python أو توجيه /api/* إلى خادم التطبيق.');throw Error(`${t('failure')} · HTTP ${r.status}: لم تُحلل استجابة HTML كـ JSON`)}let j;try{j=await r.json()}catch(_){throw Error('استجابة JSON غير صالحة.')}if(!r.ok){if(r.status===401&&me){let role=me.role;me=null;csrf=null;location.hash='#/'+({COMPANY_ADMINISTRATOR:'company',SUPERVISOR:'supervisor',WORKER:'worker'}[role]||'worker')+'/login'}throw Error(j.error||t('failure'))}return j}
