function landing(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';app.innerHTML=`${header()}<main id="main"><section class="hero"><div class="container hero-grid"><div class="hero-copy"><span class="eyebrow">${t('eyebrow')}</span><h1>${t('heroA')}<br><em>${t('heroB')}</em></h1><p>${t('heroText')}</p><div class="hero-actions"><a class="button primary" href="#portals">${t('explore')} ${icon('arrow')}</a><a class="button outline" href="#how">${t('how')} ${icon('arrow')}</a></div><div class="hero-footnote">${icon('shield')} ${t('concept')}</div></div><div class="hero-visual"><img src="/images/desert-shade-concept.jpg" alt="تصوّر توضيحي لعامل في بيئة عمل مكشوفة" fetchpriority="high"><span class="hero-index">Z / 01 — FIELD CONCEPT</span><div class="visual-caption"><span><b>DESERT SHADE</b>Concept visual · not a product photo</span><span class="pill"><span class="dot"></span> SIMULATED</span></div></div><div class="hero-meta">ZILL · PEOPLE FIRST · INFORMATION WITH CONTEXT</div></div></section><section class="trust-strip"><div class="container trust-inner"><div class="trust-item"><span class="trust-num">01</span>العامل أولًا</div><div class="trust-item"><span class="trust-num">02</span>تعيين محدد</div><div class="trust-item"><span class="trust-num">03</span>صلاحيات واضحة</div><div class="trust-item"><span class="trust-num">04</span>لا بيانات مختلقة</div></div></section><section class="section problem-section" id="problem"><div class="container problem-grid"><div class="problem-aside"><span class="eyebrow">01 / THE CONTEXT</span><h2 class="section-title">${t('problemTitle')}</h2><p class="section-copy">${t('problemText')}</p><div class="problem-quote">الوضوح يبدأ بتحديد ما نعرفه، وما لا نعرفه، ومن يحق له الاطلاع عليه.</div></div><div class="problem-points"><article class="problem-point"><span class="point-num">A</span><h3>العمل في بيئة مكشوفة</h3><p>الظروف الميدانية تتطلب إجراءات مناسبة؛ المنصة لا تحل محلها.</p></article><article class="problem-point"><span class="point-num">B</span><h3>تشتت سجلات الإسناد</h3><p>قد لا تكون علاقة العامل بالموقع والفريق والمعدة ظاهرة في مكان واحد.</p></article><article class="problem-point"><span class="point-num">C</span><h3>المعلومات بلا مصدر</h3><p>يجب تمييز المجهول والمحاكاة عن المعلومة المقاسة فعلًا.</p></article><article class="problem-point"><span class="point-num">D</span><h3>مساءلة المتابعة</h3><p>الإقرار بالتنبيه خطوة، والمعالجة والحل خطوتان منفصلتان.</p></article></div></div></section><section class="section solution-section" id="solution"><div class="container solution-split"><div><span class="eyebrow">02 / THE SYSTEM</span><h2 class="section-title">${t('solutionTitle')}</h2><p class="section-copy">ترتبط السترة بالتعيين المحدد، وتظهر لكل مستخدم المعلومات الواقعة ضمن صلاحيات دوره ونطاقه.</p><div class="solution-steps">${[['01','تسجيل العامل والنطاق','الحساب مرتبط بموقع وفريق واضحين.'],['02','إسناد سترة محددة','تعيين نشط واحد لعامل وسترة.'],['03','عرض حسب الصلاحية','العامل لنفسه، المشرف لفريقه، الشركة تجميعيًا.'],['04','متابعة موثقة','الإقرار والمعالجة والحل حالات مستقلة.']].map(x=>`<div class="solution-step"><span class="step-num">${x[0]}</span><div><b>${x[1]}</b><span>${x[2]}</span></div></div>`).join('')}</div></div><div class="solution-illustration">${journeyArt()}<span class="solution-label">${t('concept')}</span></div></div></section><section class="section workflow" id="how"><div class="container"><div class="section-head"><div><span class="eyebrow">03 / OPERATIONAL JOURNEY</span><h2 class="section-title">${t('howTitle')}</h2></div><p class="section-copy">عامل ← موقع وفريق ← تعيين وسترة ← معلومات متاحة وصلاحيات دورية.</p></div><div class="workflow-track">${[['تسجيل العامل','حساب مستقل'],['تحديد النطاق','الموقع والفريق'],['إسناد السترة','معرّف محدد'],['مساحة العامل','تعيينه فقط'],['متابعة المشرف','فريقه فقط'],['ملخص الشركة','تجميعي افتراضيًا']].map((x,i)=>`<article class="workflow-node"><b><span class="point-num">0${i+1}</span> ${x[0]}</b><p>${x[1]}</p></article>`).join('')}</div></div></section><section class="section portal-section" id="portals"><div class="container"><div class="section-head"><div><span class="eyebrow">04 / THREE WORKSPACES</span><h2 class="section-title">${t('portalTitle')}</h2></div><p class="section-copy">${t('portalText')}</p></div><div class="portal-grid">${[['COMPANY_ADMINISTRATOR','company','النطاق والمخزون والتقارير','المواقع والفرق والحسابات؛ العاملون بأرقام تشغيلية ما لم يمنحوا الموافقة.'],['SUPERVISOR','supervisor','فريق موقع محدد','التعيينات ضمن الموقع والفريق، ومتابعة التنبيهات.'],['WORKER','worker','مساحتك الشخصية','التعيين المحدد ومعلوماتك وإشعاراتك فقط.']].map((x,i)=>`<article class="portal-card" data-role-card="${x[0]}"><div class="portal-card-top"><span class="portal-glyph">${icon(x[0]==='WORKER'?'people':x[0]==='SUPERVISOR'?'site':'grid')}</span><span class="portal-stamp">/ 0${i+1}</span></div><h3>${t(x[1])}</h3><p>${x[2]}</p><ul>${x[3].split('،').map(y=>`<li>${y}</li>`).join('')}</ul><a class="button outline" href="#/${x[1]}/login">الدخول إلى البوابة ${icon('arrow')}</a></article>`).join('')}</div></div></section><section class="section capabilities"><div class="container"><span class="eyebrow">05 / WORKING CAPABILITIES</span><h2 class="section-title">${t('capTitle')}</h2><div class="capability-grid">${[['site',t('cap1'),'مواقع وفرق وحسابات بعمليات Backend فعلية.'],['vest',t('cap2'),'تعيين واحد نشط مع تحقق تعارض في الخادم.'],['bell',t('cap3'),'مسار التنبيه يسجل الإقرار والمعالجة والحل.'],['shield',t('cap4'),'بيانات حسب الدور وموافقة العامل الفردية.']].map(x=>`<article class="capability"><span class="icon-box">${icon(x[0])}</span><h3>${x[1]}</h3><p>${x[2]}</p><span class="state">● تعمل في بيئة العرض</span></article>`).join('')}</div></div></section><section class="section product-section" id="product"><div class="container product-grid"><div class="product-frame"><img src="/images/vest-concept-illustration.png" alt="رسم مفاهيمي كامل للسترة، لا صورة منتج مصنع" loading="lazy"><span class="pill product-tag"><span class="dot"></span>${t('concept')}</span></div><div><span class="eyebrow">06 / CONCEPTUAL PRODUCT</span><h2 class="section-title">${t('productTitle')}</h2><p class="section-copy">${t('productText')}</p><div class="product-notes"><div class="product-note"><span class="note-index">01</span><div><b>رسم مستند إلى التوجه المقدم</b><p>لا يثبت وجود نموذج مادي أو تحقق ميداني.</p></div></div><div class="product-note"><span class="note-index">02</span><div><b>لا أجهزة متصلة</b><p>لا توجد قراءات أو حالة حية في بيئة العرض.</p></div></div><div class="product-note"><span class="note-index">03</span><div><b>معلومة ذات سياق</b><p>العلاقة تتبع العامل والتعيين النشط والسترة المحددة.</p></div></div></div></div></div></section><section class="final-cta"><div class="container cta-inner"><div><span class="eyebrow">07 / ENTER THE DEMO</span><h2>${t('finalTitle')}</h2><p>${t('finalText')}</p></div><div class="cta-buttons"><a class="button primary" href="#/company/login">بوابة الشركة</a><a class="button outline" href="#/supervisor/login">بوابة المشرف</a><a class="button outline" href="#/worker/login">بوابة العامل</a></div></div></section></main>${footer()}`;document.querySelectorAll('[data-action="lang"]').forEach(b=>b.onclick=toggleLanguage);document.querySelector('[data-action="public-menu"]')?.addEventListener('click',()=>document.getElementById('public-nav').classList.toggle('open'))}
function toggleLanguage(){lang=lang==='ar'?'en':'ar';localStorage.setItem('zill-lang',lang);render()}
const roleOf=k=>({company:'COMPANY_ADMINISTRATOR',supervisor:'SUPERVISOR',worker:'WORKER'}[k]);
function loginPage(key){
 const role=roleOf(key);if(!role){landing();return}
 const presets=role==='WORKER'?[['عبدالرحمن العتيبي','wrk-001','تعيين نشط · ZT-DEMO-01'],['نواف الحربي','wrk-002','تعيين نشط · ZT-DEMO-02'],['سعود القحطاني','wrk-003','تعيين نشط · ZT-DEMO-03'],['ماجد الغامدي','wrk-004','تعيين منتهٍ · بلا تعيين نشط'],['فيصل الدوسري','wrk-005','لا يوجد تعيين سابق']]:role==='SUPERVISOR'?[['مشرف الموقع','supervisor','فريق وموقع تجريبي']]:[['مدير الشركة','admin','إدارة النطاق التنظيمي']];
 selectedDemo=null;
 app.innerHTML=`<main class="login-page"><section class="login-main"><div class="login-brand">${brand()}</div><div class="login-content"><a class="back-link" href="#/">${icon('arrow')} ${t('back')}</a><div class="login-intro"><span class="eyebrow">ZILL / ${t(role)}</span><h1>${t('loginTitle')}</h1><p>${t('loginText')}</p></div>
 <div class="demo-head"><div><h2>${t('selectDemo')}</h2><p>${lang==='ar'?'اضغط اختيار الحساب لعرض بياناته، أو ادخل مباشرة بنقرة واحدة.':'Select an account to reveal its credentials, or sign in with one click.'}</p></div><span class="pill">${role==='WORKER'?'05':'01'} / ${role}</span></div>
 <div class="demo-grid" id="demo-grid">${presets.map((x,i)=>`<article class="demo-card" data-demo-index="${i}"><button class="demo-card-pick" type="button" data-demo-pick disabled><span class="demo-avatar">${esc(x[0].slice(0,1))}</span><span class="demo-info"><b>${esc(x[0])}</b><small>${esc(x[1])} · ${esc(x[2])}</small></span><span class="demo-select">${t('pick')}</span></button><div class="demo-credentials" hidden><span>${t('loginUser')}</span><code data-demo-username></code><span>${t('loginPass')}</span><code data-demo-password dir="ltr"></code></div><button class="button primary small demo-fast-login" type="button" data-demo-login disabled>${t('quickLogin')} ${icon('arrow')}</button></article>`).join('')}</div><div class="demo-status" id="demo-status">${t('loading')}</div>
 <form class="login-form" id="login-form"><div class="form-row"><label class="field-label" for="username">${t('username')}</label><input class="field" id="username" name="username" autocomplete="username" required maxlength="80" dir="ltr"></div><div class="form-row"><label class="field-label" for="password">${t('password')} · ${lang==='ar'?'تظهر للمراجعة':'visible for review'}</label><input class="field" id="password" name="password" type="text" autocomplete="current-password" required maxlength="200" dir="ltr"></div><div class="login-error" id="login-error" role="alert"></div><button class="button primary full" type="submit">${t('signIn')} ${icon('arrow')}</button></form></div></section><aside class="login-aside"><img src="/images/desert-shade-concept.jpg" alt="" aria-hidden="true"><span class="login-aside-label">ZILL / DESERT SHADE · ${t(role)}</span><div class="login-aside-bottom">${t('solutionTitle')}<small>${t('concept')} · ${t('demo')}</small></div><span class="login-side-image-note">صورة تصورية · لا تمثل منتجًا مصنعًا</span></aside></main>`;
 document.getElementById('login-form').onsubmit=e=>loginSubmit(e,role);loadDemo(role,presets)
}
async function loadDemo(role,presets){
 const grid=document.getElementById('demo-grid'),status=document.getElementById('demo-status');
 try{
  const d=await api('/api/demo/accounts?role='+role),users=d.accounts;
  for(const card of grid.querySelectorAll('.demo-card')){
   const i=Number(card.dataset.demoIndex),u=users.find(x=>x.username===presets[i][1])||users[i];
   if(!u){card.hidden=true;continue}
   const pick=card.querySelector('[data-demo-pick]'),fast=card.querySelector('[data-demo-login]');pick.disabled=false;fast.disabled=false;
   card.dataset.username=u.username;card.dataset.password=u.password;
   card.querySelector('[data-demo-username]').textContent=u.username;card.querySelector('[data-demo-password]').textContent=u.password;
   const select=()=>{selectedDemo=u;grid.querySelectorAll('.demo-card').forEach(x=>x.classList.remove('selected'));card.classList.add('selected');card.querySelector('.demo-credentials').hidden=false;const f=document.getElementById('login-form');f.elements.username.value=u.username;f.elements.password.value=u.password;document.getElementById('login-error').textContent='';status.textContent=t('selected')+' · '+(u.scenario||'')};
   pick.onclick=select;
   fast.onclick=()=>{select();document.getElementById('login-form').requestSubmit()};
  }
  status.textContent=users.length?t('demo')+' · '+(lang==='ar'?'حسابات متحققة من قاعدة البيانات':'accounts verified against the database'):t('failure');
  if(users.length!==presets.length)status.classList.add('demo-warn')
 }catch(e){status.textContent=t('failure')+' · '+e.message;status.classList.add('demo-warn')}
}

async function loginSubmit(e,role){e.preventDefault();const f=e.currentTarget,b=f.querySelector('button'),err=document.getElementById('login-error');b.disabled=true;err.textContent='';try{await api('/api/login',{method:'POST',body:JSON.stringify({username:f.elements.username.value,password:f.elements.password.value,role})});const s=await api('/api/session');me=s.user;csrf=s.csrf;if(!me||me.role!==role)throw Error(t('roleError'));location.hash='#/'+({COMPANY_ADMINISTRATOR:'company',SUPERVISOR:'supervisor',WORKER:'worker'}[role])+'/overview';await render()}catch(x){err.textContent=x.message}finally{b.disabled=false}}
const C_NAV=[['overview','grid'],['sites','site'],['teams','grid'],['people','people'],['vests','vest'],['consent','shield'],['activity','activity'],['reports','file']];
const S_NAV=[['overview','grid'],['team','people'],['assignments','vest'],['alerts','bell'],['activity','activity']];
const W_NAV=[['overview','grid'],['myVest','vest'],['notifications','bell'],['profile','people'],['security','shield']];
function title(k){return t(k)||k}
function shell(role,key){const isWorker=role==='WORKER',nav=role==='COMPANY_ADMINISTRATOR'?C_NAV:role==='SUPERVISOR'?S_NAV:W_NAV,display=me?.name||t(role);let side=`<aside class="app-side ${role==='SUPERVISOR'?'supervisor':isWorker?'worker':''} ${menuOpen?'open':''}"><div class="side-profile"><span class="side-avatar">${esc(display.slice(0,1))}</span><span><b>${esc(display)}</b><small>${t(role)}</small></span></div><div class="side-caption">${role==='SUPERVISOR'?'SITE / TEAM':isWorker?'PERSONAL / PRIVATE':'ORGANIZATION / 01'}</div><nav class="side-nav">${nav.map(([k,i])=>`<button class="side-link ${key===k?'active':''}" data-go="${role==='COMPANY_ADMINISTRATOR'?'company':role==='SUPERVISOR'?'supervisor':'worker'}/${k}">${icon(i)}<span>${t(k)}</span></button>`).join('')}</nav><div class="side-bottom"><div class="side-demo">${icon('shield')} ${t('demo')}</div><button class="side-link" data-action="logout">${icon('logout')} ${t('logout')}</button></div></aside>`;return `<div class="app-shell" data-role="${role}"><header class="app-topbar"><div class="app-top-left"><button class="mobile-menu-button" data-action="toggle-side">${icon('menu')}</button><a class="app-logo" href="#/">ظِل · ZILL<small>${role==='COMPANY_ADMINISTRATOR'?'COMPANY OPERATIONS':role==='SUPERVISOR'?'FIELD WORKSPACE':'WORKER SPACE'}</small></a></div><div class="app-top-right"><span class="secure-label">${icon('shield')} ${lang==='ar'?'جلسة تجريبية آمنة':'Secure demo session'}</span>${langButton()}<button class="button outline small" data-action="logout">${icon('logout')} ${t('logout')}</button></div></header>${side}<main class="app-main" id="main"><div class="app-page-head"><div><span class="eyebrow">${role==='COMPANY_ADMINISTRATOR'?'ORGANIZATION / CONTROL':role==='SUPERVISOR'?'FIELD / SITE OPERATIONS':'MY SPACE / PRIVATE'}</span><h1>${title(key)}</h1><p>${desc(role,key)}</p></div><div class="page-actions"><button class="button outline small" data-action="reload">${icon('refresh')} ${t('refresh')}</button></div></div><div class="classification-banner sim">${icon('shield')}<span>${t('demoOnly')}</span><b>${t('simulated')}</b></div><div id="page-content">${t('loadingData')}</div></main>${isWorker?`<nav class="worker-mobile-nav">${W_NAV.map(([k,i])=>`<button class="${k===key?'active':''}" data-go="worker/${k}">${icon(i)}<span>${t(k)}</span></button>`).join('')}</nav>`:''}</div>`}
function desc(role,key){const ar={COMPANY_ADMINISTRATOR:{overview:'مؤشرات محسوبة من سجلات المؤسسة.',sites:'المواقع ضمن المؤسسة الواحدة.',teams:'الفرق مرتبطة بموقع محدد.',people:'إدارة الحسابات والنطاق التنظيمي؛ الاسم الفردي يحتاج موافقة العامل.',vests:'إدارة المخزون لا تعني وجود جهاز متصل.',consent:'طلبات الوصول وموافقات العامل المؤقتة.',activity:'أحداث التغيير المسجلة في بيئة العرض.',reports:'ملخص قاعدة البيانات؛ لا يمثل قياسًا ميدانيًا.'},SUPERVISOR:{overview:'موقع وفريق ضمن نطاق حسابك.',team:'أفراد الفريق المسند فقط.',assignments:'إسناد أو إنهاء السترة ضمن نطاق الموقع والفريق.',alerts:'البلاغ والإقرار والمعالجة والحل.',activity:'سجل التنبيهات ضمن موقعك.'},WORKER:{overview:'تعيينك ومعلوماتك المتاحة.',myVest:'السترة من تعيين حسابك الحالي فقط.',notifications:'إشعارات مرتبطة بتعيينك النشط.',profile:'معلومات حسابك.',security:'موافقة فردية محددة المدة.'}};return ar[role]?.[key]||t(key)}
function metric(label,value,foot=''){return `<article class="metric-card"><div class="metric-label">${esc(label)}</div><div class="metric-value">${esc(value)}</div><div class="metric-foot">${esc(foot)}</div></article>`}
function badge(s){let labels={ACTIVE:'نشط',ENDED:'منتهٍ',EXPIRED:'منتهٍ',AVAILABLE:'متاح',ASSIGNED:'مسند',READY:'جاهزة',MAINTENANCE:'صيانة',RETIRED:'متقاعدة',NEW:'جديد',ACKNOWLEDGED:'تم الإقرار',IN_PROGRESS:'قيد المعالجة',RESOLVED:'تم الحل',PENDING:'معلق',GRANTED:'ممنوح مؤقتًا',DENIED:'مرفوض',REVOKED:'مسحوب'};let c=['NEW','EXPIRED','MAINTENANCE'].includes(s)?'danger':['ACKNOWLEDGED','IN_PROGRESS','PENDING'].includes(s)?'warn':['RETIRED','RESOLVED','ENDED','DENIED','REVOKED'].includes(s)?'muted':'';return `<span class="tag ${c}"><span class="dot"></span>${labels[s]||s}</span>`}
function fmt(s){if(!s)return'—';try{return new Intl.DateTimeFormat(lang==='ar'?'ar-SA':'en-GB',{dateStyle:'medium',timeStyle:'short'}).format(new Date(s))}catch(_){return s}}
async function companyData(){let [overview,sites,teams,workers,sups,vests,access]=await Promise.all(['/api/company/overview','/api/sites','/api/teams','/api/company/workers','/api/company/supervisors','/api/company/vests','/api/company/access-requests'].map(p=>api(p)));return{overview,sites:sites.items,teams:teams.items,workers:workers.items,sups:sups.items,vests:vests.items,access:access.items}}
function sitePanel(d){return `<div class="panel"><div class="panel-head"><h2>${t('siteOverview')}</h2><small>${d.overview.sites.length} ${t('activeSites')}</small></div>${d.overview.sites.map(s=>`<div class="site-row"><div class="row-primary"><span class="row-icon">${icon('site')}</span><span><b>${esc(s.name)}</b><small>${esc(s.code)} · ${esc(s.region||'—')}</small></span></div><div class="row-trailing"><span class="tag">${s.workers} ${t('workers')}</span><span class="tag warn">${s.open_alerts} ${t('openAlerts')}</span></div></div>`).join('')||`<div class="empty-state">${t('empty')}</div>`}</div>`}
async function companyView(key){let d=await companyData(),m=d.overview.metrics;if(key==='overview')return `<div class="metric-grid">${metric(t('workers'),m.workers)}${metric(t('activeAssignments'),m.active_assignments)}${metric(t('unassigned'),m.without_active)}${metric(t('vestsAvailable'),m.vests_available)}${metric(t('openAlerts'),m.open_alerts)}${metric(t('activeSites'),m.sites)}${metric(t('activeTeams'),m.teams)}</div><div class="content-grid">${sitePanel(d)}<div class="panel"><div class="panel-head"><h2>${t('recent')}</h2></div>${d.overview.activity.slice(0,7).map(a=>`<div class="list-row"><span><b>${esc(a.action)}</b><small>${esc(a.entity)} #${esc(a.entity_id)} · ${fmt(a.created_at)}</small></span></div>`).join('')||t('empty')}</div></div><p class="classification-note">${t('reportNote')}</p>`;if(key==='sites')return companySites(d);if(key==='teams')return companyTeams(d);if(key==='people')return companyPeople(d);if(key==='vests')return companyVests(d);if(key==='consent')return companyConsent(d);if(key==='reports')return companyReports(d);if(key==='activity'){let a=await api('/api/audit');return auditTable(a.items)}return `<div class="panel">${t('unknownRoute')}</div>`}
function companySites(d){return `<div class="toolbar"><button class="button primary" data-action="new-site">${icon('plus')} ${t('newSite')}</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>${t('site')}</th><th>${t('code')}</th><th>${t('region')}</th><th>${t('teams')}</th><th>${t('workers')}</th><th>${t('status')}</th><th>${t('actions')}</th></tr></thead><tbody>${d.sites.map(s=>`<tr><td>${esc(s.name)}</td><td dir="ltr">${esc(s.code)}</td><td>${esc(s.region||'—')}</td><td>${s.teams}</td><td>${s.workers}</td><td>${s.active?badge('ACTIVE'):badge('RETIRED')}</td><td><button class="button outline small" data-edit-site="${s.id}">${t('edit')}</button>${s.active?` <button class="button danger small" data-archive-site="${s.id}">${t('archive')}</button>`:''}</td></tr>`).join('')}</tbody></table></div>`}
function companyTeams(d){return `<div class="toolbar"><button class="button primary" data-action="new-team">${icon('plus')} ${t('newTeam')}</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>${t('teamName')}</th><th>${t('code')}</th><th>${t('site')}</th><th>${t('status')}</th><th>${t('actions')}</th></tr></thead><tbody>${d.teams.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.code)}</td><td>${esc(x.site_name)}</td><td>${badge(x.active?'ACTIVE':'RETIRED')}</td><td><button class="button outline small" data-edit-team="${x.id}">${t('edit')}</button>${x.active?` <button class="button danger small" data-archive-team="${x.id}">${t('archive')}</button>`:''}</td></tr>`).join('')}</tbody></table></div>`}
function companyPeople(d){return `<div class="toolbar"><button class="button primary" data-action="new-worker">${icon('plus')} ${t('newWorker')}</button><button class="button outline" data-action="new-supervisor">${icon('plus')} ${t('newSupervisor')}</button><input class="search-field" id="worker-filter" placeholder="${t('search')}"></div><div class="panel"><div class="panel-head"><h2>${t('people')}</h2></div><p class="classification-note">${t('privacy')}</p><div class="table-wrap"><table class="data-table"><thead><tr><th>${t('id')}</th><th>${t('name')}</th><th>${t('site')}</th><th>${t('teamName')}</th><th>${t('assignment')}</th><th>${t('consent')}</th><th>${t('actions')}</th></tr></thead><tbody id="workers-body">${d.workers.map(w=>`<tr data-filter="${esc((w.employee_id+' '+w.site_name+' '+w.team_name+' '+(w.name||'')).toLowerCase())}"><td>${esc(w.employee_id)}</td><td>${w.consent_active?esc(lang==='en'?(w.name_en||w.name):(w.name||w.name_en)):'محجوب · '+t('requestAccess')}</td><td>${esc(w.site_name||'—')}</td><td>${esc(w.team_name||'—')}</td><td>${badge(w.assignment_status||'AVAILABLE')} ${esc(w.vest_code||'')}</td><td>${w.consent_active?badge('GRANTED'):w.assignment_consent_active?'<span class="tag">ASSIGNMENT · GRANTED</span>':badge('PENDING')}</td><td><button class="button outline small" data-worker-org="${w.id}">${t('changeOrg')}</button> <button class="button outline small" data-consent-request="${w.id}">${t('requestAccess')}</button> <button class="button ${w.active?'danger':'outline'} small" data-worker-status="${w.id}" data-active="${w.active?0:1}">${w.active?t('disable'):t('enable')}</button></td></tr>`).join('')}</tbody></table></div></div><div class="panel"><div class="panel-head"><h2>المشرفون</h2><small>${d.sups.length}</small></div><div class="table-wrap"><table class="data-table"><thead><tr><th>${t('id')}</th><th>${t('name')}</th><th>${t('site')}</th><th>${t('teamName')}</th><th>${t('status')}</th><th>${t('actions')}</th></tr></thead><tbody>${d.sups.map(s=>`<tr><td>${esc(s.employee_id)}</td><td>${esc(s.display_name||s.username)}</td><td>${esc(s.site_name||'—')}</td><td>${esc(s.team_name||'—')}</td><td>${badge(s.active?'ACTIVE':'RETIRED')}</td><td><button class="button outline small" data-supervisor-scope="${s.id}">${t('changeOrg')}</button><button class="button danger small" data-supervisor-status="${s.id}" data-active="${s.active?0:1}">${s.active?t('disable'):t('enable')}</button></td></tr>`).join('')}</tbody></table></div></div>`}
function companyVests(d){return `<div class="toolbar"><button class="button primary" data-action="new-vest">${icon('plus')} ${t('newVest')}</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>${t('vest')}</th><th>${t('site')}</th><th>${t('status')}</th><th>${t('assignment')}</th><th>${t('actions')}</th></tr></thead><tbody>${d.vests.map(v=>`<tr><td dir="ltr"><b>${esc(v.code)}</b></td><td>${esc(v.site_name)}</td><td>${badge(v.status)}</td><td>${badge(v.availability)}</td><td>${v.availability==='AVAILABLE'&&v.status!=='RETIRED'?`<button class="button outline small" data-vest-status="${v.id}" data-status="${v.status==='MAINTENANCE'?'READY':'MAINTENANCE'}">${v.status==='MAINTENANCE'?'إرجاع للجاهزية':'صيانة'}</button>`:'—'}</td></tr>`).join('')}</tbody></table></div><p class="classification-note">معرّفات مخزون تجريبية، لا تؤكد وجود جهاز مادي.</p>`}
function companyConsent(d){return `<div class="panel"><div class="panel-head"><h2>${t('consent')}</h2></div>${d.access.map(a=>`<div class="list-row"><span><b>${esc(a.employee_id)} · ${esc(a.scope)}</b><small>${esc(a.reason)} · ${fmt(a.requested_at)}</small></span><span>${badge(a.status)} ${a.expires_at?fmt(a.expires_at):''}</span></div>`).join('')||`<div class="empty-state">${t('noConsents')}</div>`}</div><p class="classification-note">الموافقة يقررها العامل ويمكنه سحبها.</p>`}
function auditTable(items){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>${t('date')||'التاريخ'}</th><th>${t('actor')||'المنفذ'}</th><th>${t('action')}</th><th>${t('entity')||'السجل'}</th><th>${t('changes')||'التغيير'}</th></tr></thead><tbody>${items.map(a=>`<tr><td>${fmt(a.created_at)}</td><td>${esc(a.actor||a.actor_id||'SYSTEM')}</td><td>${esc(a.action)}</td><td>${esc(a.entity)} #${esc(a.entity_id)}</td><td dir="ltr">${esc(a.detail||a.note||'')}</td></tr>`).join('')}</tbody></table></div>`}
function companyReports(d){let m=d.overview.metrics;return `<div class="content-grid"><div class="panel"><div class="panel-head"><h2>${t('reports')}</h2>${badge('SIMULATED')}</div><p>${t('reportNote')}</p><div class="metric-grid">${metric(t('workers'),m.workers)}${metric(t('activeAssignments'),m.active_assignments)}${metric(t('unassigned'),m.without_active)}${metric(t('openAlerts'),m.open_alerts)}</div><button class="button primary" data-action="download-report">${icon('download')} ${t('download')}</button></div>${sitePanel(d)}</div>`}
async function supervisorData(){return api('/api/supervisor/data')}
function miniWorker(w){return `<div class="list-row"><div class="row-primary"><span class="side-avatar">${esc((w.name||'ع').slice(0,1))}</span><span><b>${esc(lang==='en'?(w.name_en||w.name):(w.name||'عامل'))}</b><small>${esc(w.employee_id)} · ${esc(w.vest_code||t('noAssignment'))}</small></span></div><div>${w.active_assignment_id?badge('ACTIVE'):badge(w.assignment_status||'AVAILABLE')}</div></div>`}
function miniAlert(a){return `<article class="notice-card alert-card"><div class="notice-title"><h3>${esc(a.title)}</h3>${badge(a.status)}</div><p>${esc(a.description)}</p><small>${a.source_class==='SIMULATED'?t('simulated'):'إدخال المشرف'} · ${fmt(a.created_at)}</small></article>`}
async function supervisorView(key){let d=await supervisorData();if(!d.site)return `<div class="panel"><h2>لا يوجد موقع وفريق مسندان لهذا الحساب.</h2><p>تواصل مع مدير الشركة لتحديث نطاق المشرف.</p></div>`;let assigned=d.workers.filter(w=>w.active_assignment_id).length,open=d.alerts.filter(a=>a.status!=='RESOLVED').length;if(key==='overview')return `<div class="supervisor-banner"><div><span class="eyebrow">موقعك المسند</span><h2>${esc(d.site.name)}</h2><p>${esc(d.team.name)} · ${d.workers.length} ${t('workers')}</p></div><span class="tag warn">${open} ${t('openAlerts')}</span></div><div class="metric-grid">${metric('حجم الفريق',d.workers.length)}${metric('بسترة نشطة',assigned)}${metric('بلا سترة نشطة',d.workers.length-assigned)}${metric(t('openAlerts'),open)}</div><div class="content-grid"><div class="panel"><div class="panel-head"><h2>${t('team')}</h2><button class="button outline small" data-go="supervisor/team">عرض الفريق</button></div>${d.workers.slice(0,6).map(miniWorker).join('')||t('empty')}</div><div class="panel"><div class="panel-head"><h2>${t('alerts')}</h2><button class="button outline small" data-go="supervisor/alerts">متابعة</button></div>${d.alerts.filter(a=>a.status!=='RESOLVED').slice(0,4).map(miniAlert).join('')||t('noAlerts')}</div></div>`;if(key==='team')return supervisorTeam(d);if(key==='assignments')return supervisorAssignments(d);if(key==='alerts')return supervisorAlerts(d);if(key==='activity')return auditTable(d.activities.map(x=>({...x,entity:'ALERT',entity_id:x.alert_title,detail:x.note,actor:x.actor})));return `<div class="panel">${t('unknownRoute')}</div>`}
function supervisorTeam(d){return `<div class="toolbar"><input class="search-field" id="team-filter" placeholder="${t('search')}"><span class="classification-note">${t('scopeNote')}</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>${t('name')}</th><th>${t('id')}</th><th>${t('assignment')}</th><th>${t('vest')}</th><th>${t('actions')}</th></tr></thead><tbody id="team-table">${d.workers.map(w=>`<tr data-filter="${esc((w.name+' '+w.name_en+' '+w.employee_id).toLowerCase())}"><td>${esc(lang==='en'?(w.name_en||w.name):(w.name||'عامل'))}</td><td>${esc(w.employee_id)}</td><td>${w.active_assignment_id?badge('ACTIVE'):badge(w.assignment_status||'AVAILABLE')}</td><td dir="ltr">${esc(w.vest_code||'—')}</td><td>${w.active_assignment_id?`<button class="button danger small" data-end-assignment="${w.active_assignment_id}">${t('endAssignment')}</button>`:`<button class="button outline small" data-assign-worker="${w.id}">${t('assignVest')}</button>`}</td></tr>`).join('')}</tbody></table></div>`}
function supervisorAssignments(d){return `<div class="toolbar"><button class="button primary" data-action="new-assignment">${icon('plus')} ${t('assignVest')}</button><span class="classification-note">${t('scopeNote')}</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>${t('worker')}</th><th>${t('vest')}</th><th>${t('status')}</th><th>الفترة</th><th>${t('actions')}</th></tr></thead><tbody>${(d.assignments||[]).map(a=>`<tr><td>${esc(a.worker_name||a.employee_id)} · ${esc(a.employee_id)}</td><td dir="ltr">${esc(a.vest_code)}</td><td>${badge(a.status)}</td><td>${esc(a.start_date)} → ${esc(a.end_date||'—')}</td><td>${a.status==='ACTIVE'?`<button class="button danger small" data-end-assignment="${a.id}">${t('endAssignment')}</button>`:'—'}</td></tr>`).join('')||`<tr><td colspan="5" class="empty-state">${t('empty')}</td></tr>`}</tbody></table></div>`}
function supervisorAlerts(d){return '<div class="toolbar"><button class="button primary" data-action="new-alert">'+icon('plus')+' '+t('addAlert')+'</button><span class="classification-note">بلاغ يدوي لا يمثل قراءة مستشعر.</span></div>'+d.alerts.map(a=>{let actions='';if(a.status==='NEW')actions='<button class="button outline small" data-alert-step="'+a.id+'" data-next="ACKNOWLEDGED">إقرار</button>';if(a.status==='ACKNOWLEDGED')actions='<button class="button outline small" data-alert-step="'+a.id+'" data-next="IN_PROGRESS">بدء المعالجة</button>';if(a.status==='IN_PROGRESS')actions='<button class="button primary small" data-alert-step="'+a.id+'" data-next="RESOLVED">حل التنبيه</button>';return '<article class="notice-card alert-card"><div class="notice-title"><div><h3>'+esc(a.title)+'</h3><p>'+esc(a.description)+'</p></div>'+badge(a.status)+'</div><small>'+t(a.source_class==='SIMULATED'?'simulated':'userReported')+' · '+fmt(a.created_at)+'</small><div class="page-actions">'+actions+'</div></article>'}).join('')||'<div class="panel empty-state">'+t('noAlerts')+'</div>'}
async function workerView(key){let d=await api('/api/worker/data');if(key==='overview')return workerOverview(d);if(key==='myVest')return workerVest(d);if(key==='notifications')return workerNotifications(d);if(key==='profile')return workerProfile(d);if(key==='security')return workerSecurity(d);return `<div class="panel">${t('unknownRoute')}</div>`}
function workerOverview(d){let u=d.user;return `<section class="worker-welcome"><div class="worker-welcome-copy"><span class="eyebrow eyebrow-light">مساحتك الشخصية</span><h1>${t('welcome')} ${esc(lang==='en'?u.name_en:u.name)}</h1><p>${esc(u.employee_id)} · ${t('demoOnly')}</p></div><div class="worker-welcome-image"><img src="/images/desert-shade-concept.jpg" alt="تصوّر توضيحي لعامل في موقع عمل" loading="lazy"></div></section>${d.assignment?`<section class="worker-assignment"><div><span class="eyebrow">${t('myAssignment')}</span><h2 dir="ltr">${esc(d.assignment.vest_code)}</h2><p>${esc(d.assignment.site_name)} · ${esc(d.assignment.team_name)}</p><small>${t('simulated')} · ${esc(d.assignment.start_date)}</small></div><div class="vest-illustration">${vestArt()}</div></section>`:`<section class="assignment-none"><strong>${t('noActiveVest')}</strong><p>${t('noActiveVestText')}</p></section>`}<div class="content-grid mt-16"><div class="panel"><div class="panel-head"><h2>${t('myNotices')}</h2><button class="button outline small" data-go="worker/notifications">عرض</button></div>${d.notifications.slice(0,3).map(n=>`<article class="notice-card"><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><small>${t('simulated')} · ${fmt(n.created_at)}</small></article>`).join('')||`<div class="empty-state">${t('noNotices')}</div>`}</div><div class="panel"><div class="panel-head"><h2>${t('noTelemetry')}</h2>${badge('UNKNOWN')}</div><p>UNKNOWN ≠ 0 · ${t('unknown')}</p><small>${t('classification')}: UNKNOWN</small></div></div>`}
function workerVest(d){return `<div class="panel"><div class="panel-head"><h2>${t('myVest')}</h2>${d.assignment?badge('ACTIVE'):badge('AVAILABLE')}</div>${d.assignment?`<div class="worker-assignment"><div><span class="eyebrow">${t('myAssignment')}</span><h2 dir="ltr">${esc(d.assignment.vest_code)}</h2><p>${esc(d.assignment.site_name)} · ${esc(d.assignment.team_name)}</p><small>${esc(d.assignment.start_date)}</small></div><div class="vest-illustration">${vestArt()}</div></div>`:`<div class="assignment-none"><strong>${t('noActiveVest')}</strong><p>${t('noActiveVestText')}</p></div>`}<p>${t('noTelemetry')}</p><small>${t('classification')}: UNKNOWN</small></div><div class="panel"><div class="panel-head"><h2>${t('past')}</h2></div>${d.past_assignments.map(a=>`<div class="list-row"><span><b dir="ltr">${esc(a.vest_code)}</b><small>${esc(a.start_date)} → ${esc(a.end_date||'—')}</small></span>${badge(a.status)}</div>`).join('')||`<div class="empty-state">${t('noAssignment')}</div>`}</div>`}
function workerNotifications(d){return d.notifications.map(n=>`<article class="notice-card"><div class="notice-title"><h3>${esc(n.title)}</h3>${badge(n.source_class)}</div><p>${esc(n.body)}</p><small>${fmt(n.created_at)} · ${t('simulated')}</small></article>`).join('')||`<div class="panel empty-state">${t('noNotices')}</div>`}
function workerProfile(d){return `<div class="panel"><div class="panel-head"><h2>${t('profile')}</h2><button class="button outline small" data-action="edit-profile">${t('edit')}</button></div><div class="metric-grid">${metric(t('name'),lang==='en'?d.user.name_en:d.user.name)}${metric(t('id'),d.user.employee_id)}${metric(t('site'),d.assignment?.site_name||'—')}${metric(t('teamName'),d.assignment?.team_name||'—')}</div><p>${t('privacy')}</p></div>`}
function workerSecurity(d){return `<div class="panel"><div class="panel-head"><h2>${t('consentTitle')}</h2>${icon('shield')}</div><p>${t('consentInfo')}</p>${d.consents.map(a=>`<article class="notice-card"><div class="notice-title"><div><h3>طلب ${esc(a.scope)} · ${esc(a.reason)}</h3><small>${fmt(a.requested_at)} ${a.expires_at?' · '+fmt(a.expires_at):''}</small></div>${badge(a.status)}</div>${a.status==='PENDING'?`<div class="page-actions"><button class="button primary small" data-consent="${a.id}" data-act="grant">${t('grant')}</button><button class="button outline small" data-consent="${a.id}" data-act="deny">${t('deny')}</button></div>`:''}${a.status==='GRANTED'?`<div class="page-actions"><button class="button danger small" data-consent="${a.id}" data-act="revoke">${t('revoke')}</button></div>`:''}</article>`).join('')||`<div class="empty-state">${t('noConsents')}</div>`}</div>`}
function shellEvents(){}
async function renderApp(role,key){if(!me||({COMPANY_ADMINISTRATOR:'company',SUPERVISOR:'supervisor',WORKER:'worker'}[me.role])!==role){toast(t('roleError'));location.hash='#/'+({COMPANY_ADMINISTRATOR:'company',SUPERVISOR:'supervisor',WORKER:'worker'}[me?.role]||role)+'/login';return}document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.documentElement.lang=lang;app.innerHTML=shell(me.role,key);shellEvents();let el=document.getElementById('page-content');try{let h=role==='company'?await companyView(key):role==='supervisor'?await supervisorView(key):await workerView(key);if(route()===`${role}/${key}`&&el)el.innerHTML=h;contentEvents()}catch(e){if(el)el.innerHTML=`<div class="panel"><b>${esc(e.message)}</b><p>تحقق من الخادم ثم أعد المحاولة.</p></div>`}}
function contentEvents(){document.querySelectorAll('[data-edit-site]').forEach(b=>b.onclick=()=>openSite(b.dataset.editSite));document.querySelectorAll('[data-edit-team]').forEach(b=>b.onclick=()=>openTeam(b.dataset.editTeam));document.querySelectorAll('[data-archive-site]').forEach(b=>b.onclick=()=>archiveSite(b.dataset.archiveSite));document.querySelectorAll('[data-archive-team]').forEach(b=>b.onclick=()=>archiveTeam(b.dataset.archiveTeam));document.querySelectorAll('[data-worker-org]').forEach(b=>b.onclick=()=>openWorkerOrg(b.dataset.workerOrg));document.querySelectorAll('[data-supervisor-scope]').forEach(b=>b.onclick=()=>openSupervisorScope(b.dataset.supervisorScope));document.querySelectorAll('[data-consent-request]').forEach(b=>b.onclick=()=>openConsent(b.dataset.consentRequest));document.querySelectorAll('[data-worker-status]').forEach(b=>b.onclick=()=>setAccountStatus('workers',b.dataset.workerStatus,b.dataset.active==='1'));document.querySelectorAll('[data-supervisor-status]').forEach(b=>b.onclick=()=>setAccountStatus('supervisors',b.dataset.supervisorStatus,b.dataset.active==='1'));document.querySelectorAll('[data-vest-status]').forEach(b=>b.onclick=()=>setVestStatus(b.dataset.vestStatus,b.dataset.status));document.querySelectorAll('[data-assign-worker]').forEach(b=>b.onclick=()=>openAssignment(b.dataset.assignWorker));document.querySelectorAll('[data-end-assignment]').forEach(b=>b.onclick=()=>endAssignment(b.dataset.endAssignment));document.querySelectorAll('[data-alert-step]').forEach(b=>b.onclick=()=>alertStep(b.dataset.alertStep,b.dataset.next));document.querySelectorAll('[data-consent]').forEach(b=>b.onclick=()=>consentDecision(b.dataset.consent,b.dataset.act));document.getElementById('worker-filter')?.addEventListener('input',e=>filter('#workers-body tr',e.target.value));document.getElementById('team-filter')?.addEventListener('input',e=>filter('#team-table tr',e.target.value))}
function filter(qs,q){document.querySelectorAll(qs).forEach(r=>r.hidden=!String(r.dataset.filter||'').includes(q.toLowerCase()))}
async function actionClick(e){const b=e.currentTarget,a=b.dataset.action;try{if(a==='new-site')return openSite();if(a==='new-team')return openTeam();if(a==='new-worker')return openWorker();if(a==='new-supervisor')return openSupervisor();if(a==='new-vest')return openVest();if(a==='new-assignment')return openAssignment();if(a==='new-alert')return openAlert();if(a==='edit-profile')return openProfile();if(a==='download-report')return reportDownload();if(a==='copy-temp'){await navigator.clipboard?.writeText(b.dataset.value);toast(t('copy'));return}if(a==='logout')return logout();if(a==='reload')return render();if(a==='toggle-side'){menuOpen=!menuOpen;document.querySelector('.app-side')?.classList.toggle('open',menuOpen);return}if(a==='lang')return toggleLanguage();if(a==='dismiss')return closeModal()}catch(x){toast(x.message)}}
async function logout(){try{await api('/api/logout',{method:'POST',body:'{}'});me=null;csrf=null;go('');toast(t('logoutDone'))}catch(e){toast(e.message)}}
async function archiveSite(id){if(!confirm('أرشفة الموقع؟'))return;await mutate(`/api/company/sites/${id}`,'DELETE',{},'sites')}
async function archiveTeam(id){if(!confirm('أرشفة الفريق؟'))return;await mutate(`/api/company/teams/${id}`,'DELETE',{},'teams')}
async function setAccountStatus(type,id,active){await mutate(`/api/company/${type}/${id}/status`,'PATCH',{active},'people')}
async function setVestStatus(id,status){await mutate(`/api/company/vests/${id}`,'PATCH',{status},'vests')}
async function endAssignment(id){if(!confirm('إنهاء التعيين النشط؟'))return;await mutate(`/api/supervisor/assignments/${id}/end`,'POST',{end_date:new Date().toISOString().slice(0,10)},'assignments')}
async function alertStep(id,next){if(next==='ACKNOWLEDGED')return mutate(`/api/supervisor/alerts/${id}/transition`,'POST',{action:next},'alerts');openTransition(id,next)}
async function mutate(path,method,body,key){try{await api(path,{method,body:JSON.stringify(body)});closeModal();toast(t('handled'));const role=me.role==='COMPANY_ADMINISTRATOR'?'company':me.role==='SUPERVISOR'?'supervisor':'worker';await renderApp(role,key)}catch(e){toast(e.message)}}
async function reportDownload(){try{let d=await api('/api/company/report.csv');let blob=new Blob([d.csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=d.filename;a.click();URL.revokeObjectURL(url);toast('تم إنشاء ملف CSV من بيانات قاعدة العرض.')}catch(e){toast(e.message)}}
function closeModal(){modalRoot.innerHTML=''}
function formBody(kind,id,html,submit){return `<form data-form="${kind}" data-id="${id||''}"><div class="form-grid">${html}</div><div class="form-actions"><button type="button" class="button outline" data-close>${t('cancel')}</button><button class="button primary">${submit||t('save')}</button></div></form>`}
function applySiteTeamFilter(){document.querySelectorAll('select[name="site_id"]').forEach(s=>s.addEventListener('change',()=>{let team=document.querySelector('select[name="team_id"]');if(!team)return;[...team.options].forEach(o=>{if(!o.value)return;const rec=window._teams?.find(x=>String(x.id)===o.value);o.hidden=!!rec&&String(rec.site_id)!==s.value})}))}
async function formSubmit(e){e.preventDefault();let f=e.currentTarget,d=Object.fromEntries(new FormData(f).entries()),id=f.dataset.id,k=f.dataset.form,path='',method='POST',key=route().split('/')[1]||'overview',payload=d;
 if(k==='site'){path='/api/company/sites'+(id?'/'+id:'');method=id?'PUT':'POST';key='sites'}
 if(k==='team'){path='/api/company/teams'+(id?'/'+id:'');method=id?'PUT':'POST';key='teams'}
 if(k==='worker'){path='/api/company/workers';key='people'}
 if(k==='supervisor'){path='/api/company/supervisors';key='people'}
 if(k==='vest'){path='/api/company/vests';key='vests'}
 if(k==='worker-org'){path=`/api/company/workers/${id}/organization`;method='PATCH';key='people'}
 if(k==='supervisor-org'){path=`/api/company/supervisors/${id}/organization`;method='PATCH';key='people'}
 if(k==='consent'){path='/api/company/access-requests';key='consent'}
 if(k==='assignment'){path='/api/supervisor/assignments';key='assignments'}
 if(k==='alert'){path='/api/supervisor/alerts';key='alerts'}
 if(k==='profile'){path='/api/worker/profile';method='PATCH';key='profile'}
 if(k==='alert-step'){path=`/api/supervisor/alerts/${id}/transition`;payload={action:f.dataset.next,note:d.note};key='alerts'}
 if(k==='consent-decision'){path=`/api/worker/consents/${id}/grant`;payload={hours:Number(d.hours)};key='security'}
 try{let result=await api(path,{method,body:JSON.stringify(payload)});closeModal();if(result.temporary_password){showModal('حساب جديد · كلمة مرور مؤقتة',`<p>${t('passwordOnce')}</p><p dir="ltr"><b>${esc(result.username)}</b></p><div class="one-time-key">${esc(result.temporary_password)}</div><div class="form-actions"><button class="button outline" data-action="copy-temp" data-value="${esc(result.temporary_password)}">${t('copy')}</button><button class="button primary" data-close>حفظ</button></div>`)}else toast(t('handled'));if(k==='profile'){me.name=d.display_name;me.name_en=d.display_name_en}let role=me.role==='COMPANY_ADMINISTRATOR'?'company':me.role==='SUPERVISOR'?'supervisor':'worker';await renderApp(role,key)}catch(err){toast(err.message)}}
function showModal(title,html){modalRoot.innerHTML=`<div class="modal-backdrop" data-close><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="modal-close" data-close>×</button></header><div class="modal-body">${html}</div></section></div>`;document.querySelector('.modal').onclick=e=>e.stopPropagation();document.querySelectorAll('[data-close]').forEach(x=>x.onclick=closeModal);document.querySelectorAll('[data-action="copy-temp"]').forEach(x=>x.onclick=async()=>{await navigator.clipboard?.writeText(x.dataset.value);toast(t('copy'))});applySiteTeamFilter();document.querySelector('.modal input,.modal select,.modal textarea')?.focus()}
function fInput(name,label,value='',type='text',required=true){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`}
function fSelect(name,label,items,value=''){return `<label>${label}<select name="${name}" required><option value="">— اختر —</option>${items.map(x=>`<option value="${x.id}" ${String(x.id)===String(value)?'selected':''}>${esc(x.name)}${x.site_name?' · '+esc(x.site_name):''}</option>`).join('')}</select></label>`}
async function openSite(id){let d=await companyData(),s=d.sites.find(x=>String(x.id)===String(id));showModal(s?'تعديل الموقع':t('newSite'),formBody('site',s?.id,`${fInput('name',t('site'),s?.name||'')}${fInput('code',t('siteCode'),s?.code||'')}${fInput('region',t('region'),s?.region||'')}`,t('save')))}
async function openTeam(id){let d=await companyData(),x=d.teams.find(a=>String(a.id)===String(id));window._teams=d.teams;showModal(x?'تعديل الفريق':t('newTeam'),formBody('team',x?.id,`${fSelect('site_id',t('site'),d.sites.filter(s=>s.active),x?.site_id||'')}${fInput('name',t('teamName'),x?.name||'')}${fInput('code',t('teamCode'),x?.code||'')}`,t('save')))}
async function openWorker(){let d=await companyData();window._teams=d.teams;showModal(t('newWorker'),`<p class="classification-note">${t('privacy')}</p>${formBody('worker','',`${fInput('username',t('username'))}${fInput('employee_id',t('employeeId'))}${fSelect('site_id',t('site'),d.sites.filter(s=>s.active))}${fSelect('team_id',t('teamName'),d.teams.filter(x=>x.active))}`,t('create'))}`)}
async function openSupervisor(){let d=await companyData();window._teams=d.teams;showModal(t('newSupervisor'),formBody('supervisor','',`${fInput('username',t('username'))}${fInput('employee_id',t('employeeId'))}${fInput('display_name',t('name'))}${fSelect('site_id',t('site'),d.sites.filter(s=>s.active))}${fSelect('team_id',t('teamName'),d.teams.filter(x=>x.active))}`,t('create')))}
async function openVest(){let d=await companyData();showModal(t('newVest'),`<p class="classification-note">معرّف مخزون فقط؛ لا يؤكد وجود جهاز مادي.</p>${formBody('vest','',`${fInput('code',t('vest'),'ZT-DEMO-06')}${fSelect('site_id',t('site'),d.sites.filter(s=>s.active))}`,t('create'))}`)}
async function openWorkerOrg(id){let d=await companyData(),w=d.workers.find(x=>String(x.id)===String(id));if(!w)return;window._teams=d.teams;showModal(t('changeOrg'),formBody('worker-org',w.id,`${fSelect('site_id',t('site'),d.sites.filter(s=>s.active),w.site_id)}${fSelect('team_id',t('teamName'),d.teams.filter(x=>x.active),w.team_id)}`,t('save')))}
async function openSupervisorScope(id){let d=await companyData(),s=d.sups.find(x=>String(x.id)===String(id));if(!s)return;window._teams=d.teams;showModal(t('changeOrg'),formBody('supervisor-org',s.id,`${fSelect('site_id',t('site'),d.sites.filter(x=>x.active),s.site_id)}${fSelect('team_id',t('teamName'),d.teams.filter(x=>x.active),s.team_id)}`,t('save')))}
async function openConsent(id){let d=await companyData(),w=d.workers.find(x=>String(x.id)===String(id));if(!w)return;showModal(t('requestAccess'),`<p>${esc(w.employee_id)} · ${t('privacy')}</p>${formBody('consent',w.id,`<label class="span-2">${t('reason')}<textarea name="reason" minlength="8" required></textarea></label><label>${t('scope')}<select name="scope"><option value="PROFILE">${t('profile')}</option><option value="ASSIGNMENT">${t('assignments')}</option></select></label>`,t('request'))}`)}
async function openAssignment(workerId){let d=await supervisorData(),workers=d.workers.filter(w=>!w.active_assignment_id&&w.active),vests=d.vests.filter(v=>v.status==='READY'&&v.availability==='AVAILABLE');showModal(t('assignVest'),`${t('scopeNote')} ${formBody('assignment','',`${fSelect('worker_id',t('selectWorker'),workers,workerId||'')}${fSelect('vest_id',t('selectVest'),vests)}${fInput('start_date',t('startDate'),new Date().toISOString().slice(0,10),'date')}`,t('assignVest'))}`)}
function openAlert(){showModal(t('addAlert'),`<p>بلاغ يدوي — لا يمثل قراءة حساس.</p>${formBody('alert','',`${fInput('title',t('title'))}<label>${t('severity')}<select name="severity"><option value="INFO">${t('info')}</option><option value="ATTENTION">${t('attention')}</option><option value="URGENT">${t('urgent')}</option></select></label><label class="span-2">${t('description')}<textarea name="description" minlength="8" required></textarea></label>`,t('create'))}`)}
function openProfile(){showModal(t('profile'),formBody('profile','',`${fInput('display_name','الاسم بالعربية',me?.name||'')}${fInput('display_name_en','Name in English',me?.name_en||'')}`,t('save')))}
function openTransition(id,next){showModal(next==='IN_PROGRESS'?'بدء المعالجة':'حل التنبيه',formBody('alert-step',id,`<label class="span-2">${t('note')}<textarea name="note" minlength="5" required></textarea></label>`,t('confirm')).replace('data-form="alert-step"','data-form="alert-step" data-next="'+next+'"'))}
function openConsentDuration(id){showModal('مدة الموافقة',formBody('consent-decision',id,`<label class="span-2">${t('duration')}<select name="hours"><option value="1">1 ساعة</option><option value="8">8 ساعات</option><option value="24" selected>24 ساعة</option></select></label>`,t('grant')))}
async function consentDecision(id,act){if(act==='grant')return openConsentDuration(id);if(act==='revoke'&&!confirm('سحب الموافقة؟'))return;try{await api(`/api/worker/consents/${id}/${act}`,{method:'POST',body:'{}'});toast(t('handled'));await renderApp('worker','security')}catch(e){toast(e.message)}}
async function boot(){try{let s=await api('/api/session');me=s.user;csrf=s.csrf;await render()}catch(e){me=null;csrf=null;landing();toast(e.message)}}
async function render(){let r=route();document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';if(!r||r==='/'||['problem','solution','how','portals','product'].includes(r)){landing();return}let p=r.split('/');if(p.length===2&&p[1]==='login'){loginPage(p[0]);return}if(p.length===2){let role=p[0];if(!me){location.hash='#/'+role+'/login';return}return renderApp(role,p[1])}landing()}
document.addEventListener('click',e=>{let b=e.target.closest('[data-go]');if(b){go(b.dataset.go);return}let c=e.target.closest('[data-close]');if(c){closeModal();return}let a=e.target.closest('[data-action]');if(a)actionClick({currentTarget:a});if(e.target.closest('[data-action="public-menu"]'))document.getElementById('public-nav')?.classList.toggle('open')});
document.addEventListener('submit',e=>{if(e.target.matches('[data-form]'))formSubmit(e)});
window.addEventListener('hashchange',()=>render());boot();
